const contentItemId = $('Webhook Trigger').first().json.body.content_item_id;
const supabaseUrl = ($env["SUPABASE_URL"] || '').replace(new RegExp('/$'), '');
const headers = {
  apikey: $env["SUPABASE_SERVICE_ROLE_KEY"],
  Authorization: 'Bearer ' + $env["SUPABASE_SERVICE_ROLE_KEY"]
};

// Use n8n's built-in httpRequest helper instead of global fetch
const makeRequest = async (url) => {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: headers,
    json: true
  });
};

// 1. Fetch and validate item state
const itemData = await makeRequest(`${supabaseUrl}/rest/v1/phase2_content_items?id=eq.${contentItemId}&select=state`);
if (!itemData || !itemData[0]) {
  throw new Error('PHASE2_PUBLISH_CONTRACT_MISMATCH: Item not found');
}

// Helper to decode Base64
const extractBase64Data = (uri) => {
  if (!uri) return '';
  const match = uri.match(/^data:.*?;base64,(.*)$/);
  if (match && match[1]) {
    return Buffer.from(match[1], 'base64').toString('utf-8');
  }
  return uri;
};

// 2. Fetch caption
const captionData = await makeRequest(`${supabaseUrl}/rest/v1/phase2_assets?content_item_id=eq.${contentItemId}&asset_type=eq.caption_output&order=created_at.desc&limit=1`);
const caption = captionData[0] ? extractBase64Data(captionData[0].asset_uri) : '';

// 3. Fetch latest visual asset batch
const latestVisData = await makeRequest(`${supabaseUrl}/rest/v1/phase2_assets?content_item_id=eq.${contentItemId}&asset_type=eq.visual_asset&order=created_at.desc&limit=1`);
let visual_assets = [];

if (latestVisData[0]) {
  const batchId = latestVisData[0].batch_id;
  if (!batchId) {
    throw new Error('MISSING_BATCH_ID_CONTRACT: The visual asset does not have a batch_id. Database view must expose batch_id.');
  }

  // Strictly filter by batch_id
  const visData = await makeRequest(`${supabaseUrl}/rest/v1/phase2_assets?content_item_id=eq.${contentItemId}&asset_type=eq.visual_asset&batch_id=eq.${batchId}&order=created_at.asc`);
  visual_assets = visData.map(d => extractBase64Data(d.asset_uri));
}

if (!caption && visual_assets.length === 0) {
  throw new Error('PHASE2_PUBLISH_CONTRACT_MISMATCH: No assets found');
}

return { json: { caption, visual_assets } };

const payload = $('Fetch Assets').first().json;
const accessToken = $('Redeem BYOK Token').first().json.data.access_token;
const pageId = $('Redeem BYOK Token').first().json.data.page_id;
const contentItemId = $('Webhook Trigger').first().json.body.content_item_id;
const organizationId = $('Webhook Trigger').first().json.body.organization_id;
const threadId = $('Webhook Trigger').first().json.body.thread_id;

const images = payload.visual_assets || [];
let formattedCaption = payload.caption || '';
// Auto-format spacing for emojis that act as bullets after punctuation
formattedCaption = formattedCaption.replace(/([.!?])\s+(\p{Emoji})/gu, '$1\n\n$2');
let batch = [];

if (images.length === 1) {
  const url = images[0].startsWith('http') ? images[0] : (($env["API_BASE_URL"] || 'https://agent.pnmediaplus.com') + images[0]);
  batch.push({
    method: "POST",
    relative_url: `${pageId}/photos`,
    body: `url=${encodeURIComponent(url)}&message=${encodeURIComponent(formattedCaption)}&published=true`
  });
} else if (images.length > 1) {
  let attachedMedia = [];
  images.forEach((img, i) => {
    const url = img.startsWith('http') ? img : (($env["API_BASE_URL"] || 'https://agent.pnmediaplus.com') + img);
    batch.push({
      method: "POST",
      relative_url: `${pageId}/photos`,
      name: `photo${i}`,
      omit_response_on_success: false,
      body: `url=${encodeURIComponent(url)}&published=false`
    });
    attachedMedia.push({ "media_fbid": `{result=photo${i}:$.id}` });
  });

  batch.push({
    method: "POST",
    relative_url: `${pageId}/feed`,
    body: `message=${encodeURIComponent(formattedCaption)}&attached_media=${encodeURIComponent(JSON.stringify(attachedMedia))}`
  });
}

return {
  caption: formattedCaption,
  visual_assets: images,
  batch_payload: JSON.stringify(batch),
  accessToken: accessToken,
  pageId: pageId,
  contentItemId: contentItemId,
  organizationId: organizationId,
  threadId: threadId
};

let threadId = '';
let contentItemId = 'unknown';
let organizationId = $env['ORGANIZATION_ID'] || '';
let errorMessage = $json.execution?.error?.message || 'Unknown Error';

try {
  const webhook = $('Webhook Trigger').first();
  if (webhook && webhook.json && webhook.json.body) {
    const b = webhook.json.body;
    if (b.threadId) threadId = b.threadId;
    if (b.content_item_id) contentItemId = b.content_item_id;
    if (b.organization_id) organizationId = b.organization_id;
  }
} catch (e) {}

return {
  json: {
    threadId: threadId || 'fallback-thread',
    contentItemId: contentItemId || 'unknown',
    organizationId: organizationId || 'unknown',
    errorMessage
  }
};

const items = $input.all();
let responses = [];

if (items.length === 1 && Array.isArray(items[0].json)) {
  responses = items[0].json;
} else if (items.length === 1 && Array.isArray(items[0].json.data)) {
  responses = items[0].json.data;
} else {
  // n8n split the batch array into multiple items
  responses = items.map(item => item.json);
}

let externalId = '';

for (let i = 0; i < responses.length; i++) {
  const res = responses[i];

  // Direct error object
  if (res.error && !res.code) {
    throw new Error('Facebook API Error: ' + res.error.message);
  }

  // Batch response error
  if (res.code && res.code !== 200) {
    let body = res.body;
    try { if (typeof body === 'string') body = JSON.parse(body); } catch(e) {}
    const errorMsg = body?.error?.message || 'Unknown batch error';
    throw new Error(`Facebook Batch Error at step ${i}: ${errorMsg}`);
  }
}

const lastOp = responses[responses.length - 1];
let lastBody = lastOp.body;

try {
  if (typeof lastBody === 'string') lastBody = JSON.parse(lastBody);
} catch(e) {}

if (!lastBody && lastOp.id) {
  lastBody = lastOp;
}

externalId = lastBody?.post_id || lastBody?.id || '';

if (!externalId) {
  throw new Error('Unexpected Facebook API response: ' + JSON.stringify(responses));
}

return [{ 
  json: { 
    id: externalId, 
    status: 'ok', 
    fbResponse: responses 
  },
  pairedItem: { item: 0 }
}];
